package com.snehal.sso.auth.config; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.slf4j.MDC; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.UUID;
@Component public class CorrelationIdFilter extends OncePerRequestFilter { @Override protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String id=r.getHeader("X-Correlation-Id");if(id==null||id.isBlank())id=UUID.randomUUID().toString();MDC.put("correlationId",id);s.setHeader("X-Correlation-Id",id);try{c.doFilter(r,s);}finally{MDC.remove("correlationId");}} }
